import unittest

from textstats import stats


class StatsTest(unittest.TestCase):
    def test_counts(self):
        got = stats("The cat, the DOG.\nthe end!\n\nCat dog cat\n")
        self.assertEqual(got, {"lines": 4, "words": 9, "chars": 40, "top_word": "the"})

    def test_tie_goes_to_first(self):
        self.assertEqual(stats("b a")["top_word"], "b")


if __name__ == "__main__":
    unittest.main()
